            if (pin.Id == null)
                throw new ArgumentNullException(nameof(pin.Id), "Property is required for class Pin.");

            if (pin.AiDisclosuresOption.IsSet && pin.AiDisclosures == null)
                throw new ArgumentNullException(nameof(pin.AiDisclosures), "Property is required for class Pin.");

            if (pin.BoardIdOption.IsSet && pin.BoardId == null)
                throw new ArgumentNullException(nameof(pin.BoardId), "Property is required for class Pin.");

            if (pin.BoardOwnerOption.IsSet && pin.BoardOwner == null)
                throw new ArgumentNullException(nameof(pin.BoardOwner), "Property is required for class Pin.");

            if (pin.MediaOption.IsSet && pin.Media == null)
                throw new ArgumentNullException(nameof(pin.Media), "Property is required for class Pin.");

            writer.WriteString("id", pin.Id);

            if (pin.AiDisclosuresOption.IsSet)
            {
                writer.WritePropertyName("ai_disclosures");
                JsonSerializer.Serialize(writer, pin.AiDisclosures, jsonSerializerOptions);
            }
            if (pin.BoardIdOption.IsSet)
                writer.WriteString("board_id", pin.BoardId);

            if (pin.BoardOwnerOption.IsSet)
            {
                writer.WritePropertyName("board_owner");
                JsonSerializer.Serialize(writer, pin.BoardOwner, jsonSerializerOptions);
            }
            if (pin.BoardSectionIdOption.IsSet)
                if (pin.BoardSectionIdOption.Value != null)
                    writer.WriteString("board_section_id", pin.BoardSectionId);
                else
                    writer.WriteNull("board_section_id");

            if (pin.CreatedAtOption.IsSet)
                writer.WriteString("created_at", pin.CreatedAtOption.Value!.Value.ToString(CreatedAtFormat));

            if (pin.CreativeTypeOption.IsSet)
                if (pin.CreativeTypeOption!.Value != null)
                {
                    var creativeTypeRawValue = CreativeTypeValueConverter.ToJsonValue(pin.CreativeTypeOption.Value!.Value);
                    writer.WriteString("creative_type", creativeTypeRawValue);
                }
                else
                    writer.WriteNull("creative_type");
            if (pin.DominantColorOption.IsSet)
                if (pin.DominantColorOption.Value != null)
                    writer.WriteString("dominant_color", pin.DominantColor);
                else
                    writer.WriteNull("dominant_color");

            if (pin.HasBeenPromotedOption.IsSet)
                writer.WriteBoolean("has_been_promoted", pin.HasBeenPromotedOption.Value!.Value);

            if (pin.IsOwnerOption.IsSet)
                writer.WriteBoolean("is_owner", pin.IsOwnerOption.Value!.Value);

            if (pin.IsProductOption.IsSet)
                writer.WriteBoolean("is_product", pin.IsProductOption.Value!.Value);

            if (pin.IsStandardOption.IsSet)
                writer.WriteBoolean("is_standard", pin.IsStandardOption.Value!.Value);

            if (pin.MediaOption.IsSet)
            {
                writer.WritePropertyName("media");
                JsonSerializer.Serialize(writer, pin.Media, jsonSerializerOptions);
            }
            if (pin.ParentPinIdOption.IsSet)
                if (pin.ParentPinIdOption.Value != null)
                    writer.WriteString("parent_pin_id", pin.ParentPinId);
                else
                    writer.WriteNull("parent_pin_id");

            if (pin.PinMetricsOption.IsSet)
                if (pin.PinMetricsOption.Value != null)
                {
                    writer.WritePropertyName("pin_metrics");
                    JsonSerializer.Serialize(writer, pin.PinMetrics, jsonSerializerOptions);
                }
                else
                    writer.WriteNull("pin_metrics");
            if (pin.AltTextOption.IsSet)
                if (pin.AltTextOption.Value != null)
                    writer.WriteString("alt_text", pin.AltText);
                else
                    writer.WriteNull("alt_text");

            if (pin.DescriptionOption.IsSet)
                if (pin.DescriptionOption.Value != null)
                    writer.WriteString("description", pin.Description);
                else
                    writer.WriteNull("description");

            if (pin.LinkOption.IsSet)
                if (pin.LinkOption.Value != null)
                    writer.WriteString("link", pin.Link);
                else
                    writer.WriteNull("link");

            if (pin.TitleOption.IsSet)
                if (pin.TitleOption.Value != null)
                    writer.WriteString("title", pin.Title);
                else
                    writer.WriteNull("title");
        }
    }
}
